template<class T>std::vector<T>readv(std::ifstream&f,size_t n){std::vector<T>x(n);f.read((char*)x.data(),n*sizeof(T));if(!f)throw std::runtime_error("inputread");return x;}
template<class T>T scalar(std::ifstream&f){return readv<T>(f,1)[0];}
template<class T>void writev(std::ofstream&f,const std::vector<T>&v){f.write((char*)v.data(),v.size()*sizeof(T));if(!f)throw std::runtime_error("outputwrite");}
struct Input {int m,n,k,nr;long long nnz,nt;std::array<float,9>parameters;std::vector<int>pm,qm,ip,iq;std::vector<mf_node>R,test,original;std::vector<uint16_t>P,Q;std::vector<float>rates;};
Input load(const std::string&name,const std::string&original_path){std::ifstream f(name,std::ios::binary);if(scalar<uint32_t>(f)!=0x4d465331U||scalar<uint32_t>(f)!=1)throw std::runtime_error("magic");Input x;x.m=scalar<int32_t>(f);x.n=scalar<int32_t>(f);x.k=scalar<int32_t>(f);x.nr=scalar<int32_t>(f);x.nnz=scalar<int64_t>(f);x.nt=scalar<int64_t>(f);f.read((char*)x.parameters.data(),36);x.pm=readv<int>(f,x.m);x.qm=readv<int>(f,x.n);x.ip=readv<int>(f,x.m);x.iq=readv<int>(f,x.n);x.R=readv<mf_node>(f,x.nnz);x.test=readv<mf_node>(f,x.nt);x.P=readv<uint16_t>(f,size_t(x.m)*x.k);x.Q=readv<uint16_t>(f,size_t(x.n)*x.k);x.rates=readv<float>(f,x.nr);if(f.peek()!=EOF)throw std::runtime_error("inputtail");std::ifstream raw(original_path,std::ios::binary);x.original=readv<mf_node>(raw,x.nnz);return x;}
inline float half_value(uint16_t x){half h;std::memcpy(&h,&x,2);return __half2float(h);}
inline uint16_t half_bits(float x){half h=__float2half(x);uint16_t y;std::memcpy(&y,&h,2);return y;}
template<class T>struct HostBuffer {void*base=nullptr;T*data=nullptr;size_t count;HostBuffer(size_t n):count(n){mfobs::check(cudaMallocHost(&base,n*sizeof(T)+512));std::memset(base,165,n*sizeof(T)+512);data=(T*)((unsigned char*)base+256);}~HostBuffer(){if(base)mfobs::check(cudaFreeHost(base));}bool guards()const{auto p=(unsigned char*)base;for(int i=0;i<256;i++)if(p[i]!=165||p[256+count*sizeof(T)+i]!=165)return false;return true;}std::vector<T>values()const{return std::vector<T>(data,data+count);}void save(const std::string&name)const{std::ofstream f(name,std::ios::binary);f.write((char*)base,count*sizeof(T)+512);}};
struct Trace {void*base=nullptr;long long*data=nullptr;size_t count;Trace(size_t n):count(n){mfobs::check(cudaMalloc(&base,n*8+512));mfobs::check(cudaMemset(base,165,n*8+512));mfobs::check(cudaDeviceSynchronize());data=(long long*)((unsigned char*)base+256);}~Trace(){if(base)mfobs::check(cudaFree(base));}std::vector<long long>capture(mfobs::State&s){auto b=s.snapshot(mfobs::Allocation{1000,base,data,count*8},"actual_selector_trace");std::vector<long long>v(count);std::memcpy(v.data(),b.data(),b.size());return v;}};
struct RNGCheck {bool valid=true;std::vector<int32_t>record_count,user_count,item_count;std::vector<uint32_t>states;};
RNGCheck validate_rng(const std::vector<long long>&trace,int workers,int epochs,int updates,int vector_size,const std::vector<mf_node>&R,int m,int n,const std::vector<unsigned char>&actual_final){RNGCheck c;c.record_count.assign(R.size(),0);c.user_count.assign(m,0);c.item_count.assign(n,0);c.states.resize(workers);for(int w=0;w<workers;w++)c.states[w]=(26757677U*(5551212U^unsigned(w))+1U)%2147483648U;size_t expected=size_t(workers)*epochs*updates;c.valid&=trace.size()==expected;for(int it=0;it<epochs;it++)for(int group=0;group<updates;group++)for(int w=0;w<workers;w++){uint32_t&s=c.states[w];s=(26757677U*s+1U)%2147483648U;float random=float(s)/float(2147483648U);float product=random*float(R.size());long long start=(long long)product%R.size();size_t idx=(size_t(it)*updates+group)*workers+w;c.valid&=trace[idx]==start;for(int j=0;j<vector_size;j++){int at=int((start+j)%R.size());c.record_count[at]++;c.user_count[R[at].u]++;c.item_count[R[at].v]++;}}c.valid&=actual_final.size()==size_t(workers)*4;for(int w=0;w<workers;w++){uint32_t got;std::memcpy(&got,actual_final.data()+w*4,4);c.valid&=got==c.states[w];}return c;}
void append_common(mfobs::State&s,const Input&x){s.prefix.insert(s.prefix.end(),{double(0x4d465331U),1.,double(x.m),double(x.n),double(x.k),double(x.nnz),double(x.nt)});for(float p:x.parameters)s.prefix.push_back(p);for(auto*v:{&x.pm,&x.qm,&x.ip,&x.iq})for(int z:*v)s.prefix.push_back(z);for(auto r:x.original)s.prefix.insert(s.prefix.end(),{double(r.u),double(r.v),double(r.rate)});for(auto r:x.test)s.prefix.insert(s.prefix.end(),{double(r.u),double(r.v),double(r.rate)});s.prefix.insert(s.prefix.end(),{257.,128.,12.,double(.0125f),double(.05f),double(.075f)});}
void append_checks(std::vector<double>&out,const RNGCheck&c,bool valid){out.push_back(valid?1.:0.);out.push_back(c.valid?1.:0.);for(uint32_t v:c.states)out.push_back(v);for(int32_t v:c.record_count)out.push_back(v);for(int32_t v:c.user_count)out.push_back(v);for(int32_t v:c.item_count)out.push_back(v);}
std::vector<double>predictions(const std::vector<float>&p,const std::vector<float>&q,const std::vector<mf_node>&R,int k){std::vector<double>v(R.size());for(size_t i=0;i<R.size();i++){double dot=0;for(int j=0;j<k;j++)dot+=double(p[size_t(R[i].u)*k+j])*double(q[size_t(R[i].v)*k+j]);v[i]=dot;}return v;}
double squared_loss(const std::vector<double>&pred,const std::vector<mf_node>&R){double sum=0;for(size_t i=0;i<R.size();i++){double e=pred[i]-R[i].rate;sum+=e*e;}return sum;}
std::vector<mf_node>original_train(const Input&x){return x.original;}
void save_science(const std::string&base,const Input&x,int workers,const std::vector<uint16_t>&halfP,const std::vector<uint16_t>&halfQ,const std::vector<float>&beforeP,const std::vector<float>&beforeQ,const std::vector<float>&finalP,const std::vector<float>&finalQ,const std::vector<double>&trainpred,const std::vector<double>&testpred){std::ofstream f(base+".science.bin",std::ios::binary);std::vector<int32_t>header={0x4d464d31,x.m,x.n,x.k,workers,30,int(x.nnz),int(x.nt)};writev(f,header);f.write((char*)x.parameters.data(),36);writev(f,halfP);writev(f,halfQ);writev(f,beforeP);writev(f,beforeQ);writev(f,finalP);writev(f,finalQ);writev(f,trainpred);writev(f,testpred);}
bool training_case(mfobs::State&s,const Input&x,int workers,int case_id,const std::string&base,std::vector<double>&out){HostBuffer<mf_node>ratings(x.nnz);std::copy(x.R.begin(),x.R.end(),ratings.data);HostBuffer<short>hp(x.P.size()),hq(x.Q.size());std::memcpy(hp.data,x.P.data(),x.P.size()*2);std::memcpy(hq.data,x.Q.data(),x.Q.size()*2);HostBuffer<float>fp(x.P.size()),fq(x.Q.size());mf_problem prob{};prob.m=x.m;prob.n=x.n;prob.nnz=x.nnz;prob.u_grid=prob.v_grid=prob.x_grid=prob.y_grid=prob.ux=prob.vy=1;prob.u_seg=x.m;prob.v_seg=x.n;prob.R=ratings.data;mf_node*grids[]={ratings.data,ratings.data+x.nnz};long long sizes[]={x.nnz};prob.R2D=grids;prob.gridSize=sizes;prob.maxGridSize=x.nnz;mf_model model{};model.m=x.m;model.n=x.n;model.k=x.k;model.u_grid=model.v_grid=model.x_grid=model.y_grid=model.ux=model.vy=1;model.u_seg=x.m;model.v_seg=x.n;model.halfp=hp.data;model.halfq=hq.data;model.floatp=fp.data;model.floatq=fq.data;model.b=x.parameters[3];Parameter para;para.k=128;para.num_iters=30;para.num_workers=workers;para.u_grid=para.v_grid=para.x_grid=para.y_grid=para.ux=para.vy=1;para.alpha=x.parameters[4];para.beta=x.parameters[5];para.lrate=x.parameters[6];para.lambda_p=x.parameters[7];para.lambda_q=x.parameters[8];int updates=(x.nnz+workers*128-1)/(workers*128);Trace trace(size_t(workers)*30*updates);study_trace_ptr=trace.data;s.epochs=30;s.open_case(base,case_id,workers,x.m,x.n,x.nnz);s.start();sgd_update_k128(para,&model,&prob,x.parameters[0]);s.stop();auto actual_trace=trace.capture(s);auto rng=validate_rng(actual_trace,workers,30,updates,128,x.R,x.m,x.n,s.released.at(0));std::vector<uint16_t>finalhp(x.P.size()),finalhq(x.Q.size());std::memcpy(finalhp.data(),hp.data,finalhp.size()*2);std::memcpy(finalhq.data(),hq.data,finalhq.size()*2);auto beforeP=fp.values(),beforeQ=fq.values();bool converted=true;for(size_t i=0;i<finalhp.size();i++)converted&=beforeP[i]==half_value(finalhp[i]);for(size_t i=0;i<finalhq.size();i++)converted&=beforeQ[i]==half_value(finalhq[i]);auto ip=x.ip,iq=x.iq;scale_model(&model,x.parameters[0]);shuffle_model(&model,ip.data(),iq.data());auto finalP=fp.values(),finalQ=fq.values();std::vector<float>initialP(x.P.size()),initialQ(x.Q.size());float factor=std::sqrt(x.parameters[0]);for(int u=0;u<x.m;u++)for(int j=0;j<x.k;j++)initialP[size_t(u)*x.k+j]=half_value(x.P[size_t(x.pm[u])*x.k+j])*factor;for(int v=0;v<x.n;v++)for(int j=0;j<x.k;j++)initialQ[size_t(v)*x.k+j]=half_value(x.Q[size_t(x.qm[v])*x.k+j])*factor;auto train=original_train(x);auto prediction=predictions(finalP,finalQ,train,x.k),heldout=predictions(finalP,finalQ,x.test,x.k),initial_prediction=predictions(initialP,initialQ,train,x.k);double loss=squared_loss(prediction,train),initial_loss=squared_loss(initial_prediction,train),test_rmse=std::sqrt(squared_loss(heldout,x.test)/x.nt);bool finite=true;for(auto*v:{&finalP,&finalQ})for(float a:*v)finite&=std::isfinite(a);for(auto*v:{&prediction,&heldout})for(double a:*v)finite&=std::isfinite(a);bool changed=finalhp!=x.P||finalhq!=x.Q;bool hostguards=ratings.guards()&&hp.guards()&&hq.guards()&&fp.guards()&&fq.guards();bool valid=finite&&changed&&converted&&hostguards&&s.valid&&rng.valid&&loss<initial_loss&&test_rmse<=3.0;out.insert(out.end(),{double(case_id),valid?1.:0.,finite?1.:0.,changed?1.:0.,converted?1.:0.,hostguards?1.:0.,loss<initial_loss?1.:0.,test_rmse<=3.?1.:0.});for(long long v:actual_trace)out.push_back(double(v));append_checks(out,rng,valid);for(int v:s.launches)out.push_back(v);if(s.capture){save_science(base,x,workers,finalhp,finalhq,beforeP,beforeQ,finalP,finalQ,prediction,heldout);ratings.save(base+".host_R.bin");hp.save(base+".host_halfP.bin");hq.save(base+".host_halfQ.bin");fp.save(base+".host_floatP.bin");fq.save(base+".host_floatQ.bin");std::ofstream j(base+".checks.json");j<<"{\"case\":"<<case_id<<",\"workers\":"<<workers<<",\"epochs\":30,\"updates_per_worker_epoch\":"<<updates<<",\"source_selector_draws\":"<<actual_trace.size()<<",\"rating_updates\":"<<actual_trace.size()*128<<",\"property_pass\":"<<(valid?"true":"false")<<",\"finite\":"<<(finite?"true":"false")<<",\"source_half_to_float_exact\":"<<(converted?"true":"false")<<",\"rng_exact\":"<<(rng.valid?"true":"false")<<",\"host_guards\":"<<(hostguards?"true":"false")<<",\"initial_train_squared_error\":"<<std::setprecision(17)<<initial_loss<<",\"final_train_squared_error\":"<<loss<<",\"heldout_dot_only_RMSE\":"<<test_rmse<<",\"kernel_launches\":[";for(int i=0;i<4;i++)j<<(i?",":"")<<s.launches[i];j<<"]}\n";}s.close_case();return valid;}
bool feature_case(mfobs::State&s,int seg,int id,const std::string&base,std::vector<double>&out){HostBuffer<short>features(seg*128);s.epochs=0;s.open_case(base,id,0,seg,128,0);init_feature(features.data,1,seg,128);auto actual=s.released.at(0),states=s.released.at(1);std::vector<uint16_t>bits(seg*128);std::memcpy(bits.data(),features.data,bits.size()*2);bool valid=features.guards()&&s.valid;float scale=float(std::sqrt(1./128));for(int i=0;i<256;i++){uint32_t seed=(26757677U*(5551212U^unsigned(i))+1U)%2147483648U;if(i<seg*128){seed=(26757677U*seed+1U)%2147483648U;float random=float(seed)/float(2147483648U);valid&=bits[i]==half_bits(random*scale);}uint32_t got;std::memcpy(&got,states.data()+i*4,4);valid&=got==seed;}valid&=actual.size()==bits.size()*2&&std::memcmp(actual.data(),bits.data(),actual.size())==0;out.insert(out.end(),{double(id),valid?1.:0.,double(seg*128)});for(auto v:bits)out.push_back(v);for(int i=0;i<256;i++){uint32_t v;std::memcpy(&v,states.data()+i*4,4);out.push_back(v);}for(int v:s.launches)out.push_back(v);if(s.capture)features.save(base+".host_features.bin");s.close_case();return valid;}
bool operator_case(mfobs::State&s,const std::string&oracle,const std::string&base,std::vector<double>&out){constexpr int n=257,k=128,workers=12;std::vector<mf_node>R(n);std::vector<uint16_t>P(n*k),Q(n*k);for(int i=0;i<n;i++){R[i]={i,i,float(i%7-3)*.25f};for(int j=0;j<k;j++){P[i*k+j]=half_bits(std::ldexp(float((i*17+j*7)%127-63)/1024.f,-int((i+j*3)%13)));Q[i*k+j]=half_bits(std::ldexp(float((i*11+j*3)%113-56)/1024.f,-int((i*5+j)%11)));}}s.epochs=1;s.open_case(base,2,workers,n,n,n);unsigned int*dstate;float*drate;mf_node*dR;half*dP,*dQ;mfobs::check(mfobs::allocate((void**)&dstate,workers*4));mfobs::check(mfobs::allocate((void**)&drate,1024*4));mfobs::check(mfobs::allocate((void**)&dR,n*sizeof(mf_node)));mfobs::check(mfobs::allocate((void**)&dP,P.size()*2));mfobs::check(mfobs::allocate((void**)&dQ,Q.size()*2));std::vector<float>rates(1024,0);rates[0]=.0125f;mfobs::check(cudaMemcpy(drate,rates.data(),4096,cudaMemcpyHostToDevice));mfobs::check(cudaMemcpy(dR,R.data(),n*sizeof(mf_node),cudaMemcpyHostToDevice));mfobs::check(cudaMemcpy(dP,P.data(),P.size()*2,cudaMemcpyHostToDevice));mfobs::check(cudaMemcpy(dQ,Q.data(),Q.size()*2,cudaMemcpyHostToDevice));mfobs::launch(0);init_rand_state<<<1,256>>>(5551212,dstate,workers);mfobs::check(cudaGetLastError());mfobs::check(cudaDeviceSynchronize());Trace trace(workers);mfobs::before_training();mfobs::launch(1);sgd_k128_kernel_hogwild_warp32_lrate<<<3,128>>>(dR,n,dP,dQ,dstate,drate,n,n,k,1,0,1,1,1,.05f,.075f,1,1,0,0,trace.data);mfobs::check(cudaGetLastError());mfobs::check(cudaDeviceSynchronize());std::vector<uint16_t>fp(P.size()),fq(Q.size());mfobs::check(cudaMemcpy(fp.data(),dP,fp.size()*2,cudaMemcpyDeviceToHost));mfobs::check(cudaMemcpy(fq.data(),dQ,fq.size()*2,cudaMemcpyDeviceToHost));auto actual_trace=trace.capture(s);mfobs::check(mfobs::release(dP));mfobs::check(mfobs::release(dQ));mfobs::check(mfobs::release(dR));mfobs::check(mfobs::release(drate));mfobs::check(mfobs::release(dstate));auto rng=validate_rng(actual_trace,workers,1,1,1,R,n,n,s.released.at(0));std::ifstream file(oracle,std::ios::binary);auto h=readv<uint32_t>(file,5);if(h!=std::vector<uint32_t>{0x4d464f31,257,128,12,3072})throw std::runtime_error("oracleheader");auto origins=readv<int32_t>(file,12);std::vector<bool>selected(n,false);for(int a:origins)selected[a]=true;bool valid=s.valid&&rng.valid;double max_error=0,max_fraction=0;for(int z=0;z<3072;z++){int which=scalar<int32_t>(file),row=scalar<int32_t>(file),j=scalar<int32_t>(file);double ideal=scalar<double>(file),bound=scalar<double>(file);double got=half_value((which?fq:fp)[row*k+j]);double error=std::abs(got-ideal);valid&=std::isfinite(got)&&error<=bound;max_error=std::max(max_error,error);max_fraction=std::max(max_fraction,error/bound);}for(int i=0;i<n;i++)if(!selected[i])for(int j=0;j<k;j++)valid&=fp[i*k+j]==P[i*k+j]&&fq[i*k+j]==Q[i*k+j];out.insert(out.end(),{2.,valid?1.:0.,3072.});for(long long v:actual_trace)out.push_back(v);append_checks(out,rng,valid);for(int v:s.launches)out.push_back(v);if(s.capture){std::ofstream f(base+".operator.bin",std::ios::binary);writev(f,fp);writev(f,fq);std::ofstream j(base+".checks.json");j<<"{\"property_pass\":"<<(valid?"true":"false")<<",\"updated_components\":3072,\"unchanged_components\":62720,\"max_ideal_absolute_error\":"<<std::setprecision(17)<<max_error<<",\"max_derived_bound_fraction\":"<<max_fraction<<",\"all12independentwarps\":true}\n";}s.close_case();return valid;}
int main(int argc,char**argv){try{static_assert(sizeof(mf_node)==12,"nodeABI");if(argc<5)throw std::runtime_error("fixture originaltrain oracle persistentroot [pilot]");Input x=load(argv[1],argv[2]);std::string folder=argv[4];bool pilot=argc==6&&std::string(argv[5])=="pilot";mfobs::State s;mfobs::state=&s;for(int trial=0;trial<=(pilot?1:5);trial++){s.capture=true;s.valid=true;s.seconds=0;s.prefix.clear();append_common(s,x);std::vector<double>out;bool valid=true;auto base=[&](int c){return folder+"/cuda_"+std::to_string(getpid())+"_trial"+std::to_string(trial)+"_case"+std::to_string(c);};valid&=feature_case(s,1,3,base(3),out);valid&=feature_case(s,2,4,base(4),out);valid&=operator_case(s,argv[3],base(2),out);valid&=training_case(s,x,12,0,base(0),out);valid&=training_case(s,x,128,1,base(1),out);if(!trial){if(!valid){auto failed=s.prefix;failed.insert(failed.end(),out.begin(),out.end());std::ofstream f("warmup_failure.bin",std::ios::binary);writev(f,failed);f.close();throw std::runtime_error("warmupindependent/guard/propertycheckfailed");}continue;}size_t prefix=s.prefix.size();if(prefix!=1524635)throw std::runtime_error("prefixshape "+std::to_string(prefix));s.prefix.insert(s.prefix.end(),out.begin(),out.end());std::string path="trial"+std::to_string(trial)+".bin";std::ofstream f(path,std::ios::binary);writev(f,s.prefix);f.close();printf("STUDY_TRIAL {\"trial\":%d,\"time_seconds\":%.17g,\"correct\":%s,\"checked_values\":%zu,\"input_prefix_values\":%zu,\"max_abs_error\":null,\"max_rel_error\":null,\"timing_region\":\"sum_two_complete_source_onepartition_SGDupdatefunctions_30epochs_workers12and128_instrumented\",\"jit_excluded\":true,\"internal_repeats\":1,\"output_artifact\":{\"path\":\"%s\",\"dtype\":\"float64\",\"count\":%zu,\"byte_order\":\"little\"}}\n",trial,s.seconds,valid?"true":"false",s.prefix.size(),prefix,path.c_str(),s.prefix.size());fflush(stdout);if(!valid)throw std::runtime_error("property/guard/independentoperatorcheckfailed");}mfobs::state=nullptr;return 0;}catch(std::exception&e){fprintf(stderr,"STUDY_ERROR %s\n",e.what());return 2;}}
